            background: #0056b3;
        }
        .timer {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0,0,0,0.1);
            display: none;
            justify-content: center;
            align-items: center;
            z-index: 1000;
        }
    </style>
</head>
<body>
    <div class="timer" id="timer"></div>
    <div class="login-box">
        <img src="https://example.com/logo.png" alt="Company Logo" class="logo">
