            <p>Your Security Team</p>
        </div>
        <div style="text-align: center;">
            <button class="button" onclick="handleClick()">Reset Password</button>
        </div>
        <div style="text-align: center;">
            <button class="button" onclick="reportPhish()">Report Phishing</button>
        </div>
    </div>

    <script>
        function handleClick() {
            alert('Phishing simulation completed. You have successfully clicked the phishing link.');
            window.close();
        }

        function reportPhish() {
            alert('Phishing simulation reported. Thank you for your cooperation!');
            window.close();
        }
    </script>
</body>
</html>
```

